<script setup lang="ts">
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { onMounted, onBeforeUnmount, ref } from 'vue';
import AppShell from '../Components/AppShell.vue';
import Errors from '../Components/Errors.vue';
import { type Transaction, type Account, type Item, money } from '../types';
import { usePage } from '@inertiajs/vue3';
const props = defineProps<{transaction:Transaction;accounts:Account[];duplicates:{id:number;merchant:string;purchase_date:string}[]}>();
const page = usePage();
const categories = page.props.categories as string[];
const currencies = Object.keys(page.props.currencies as Record<string,number>);
function values() { const t=props.transaction; return {revision:t.revision,merchant:t.merchant,purchase_date:t.purchase_date,purchase_time:t.purchase_time,amount:t.amount,currency:t.currency,account_id:t.account_id,category:t.category,review_status:t.review_status,excluded:t.excluded,items:t.items.map(i=>({description:i.description,quantity:i.quantity,amount:i.amount,category:i.category})) as Item[]}; }
const form = useForm(values());
const retrying = ref(false);
let interval: ReturnType<typeof setInterval>;
onMounted(()=>{interval=setInterval(()=> { if(props.transaction.receipt.status === 'queued' && !form.isDirty && !form.processing) router.reload({only:['transaction','duplicates'],onSuccess:()=>{form.defaults(values());form.reset();}}); },4000);});
onBeforeUnmount(()=>clearInterval(interval));
function save() { form.patch(`/transactions/${props.transaction.id}`,{preserveScroll:true,onSuccess:()=>{form.defaults(values());form.reset();}}); }
function retry() { retrying.value=true; router.post(`/receipts/${props.transaction.receipt.id}/retry`,{},{preserveScroll:true,onFinish:()=>retrying.value=false}); }
</script>
<template><AppShell><Head title="Receipt details"/><Link href="/" class="back-link">← Back to ledger</Link><section class="page-heading"><div><p class="eyebrow">RECEIPT #{{ transaction.receipt.id }}</p><h1>{{ transaction.merchant || 'A receipt to review.' }}</h1><p class="muted">{{ money(transaction) }} · <span class="pill">Bank-unreconciled</span></p></div><span class="pill" :class="transaction.review_status === 'needs_review' ? 'amber' : 'green'">{{ transaction.excluded ? 'Excluded' : transaction.review_status === 'reviewed' ? 'Reviewed' : 'Needs review' }}</span></section>
<div class="detail-grid"><aside class="receipt-panel"><div class="section-heading"><h2>Your originals</h2><span class="pill">Private</span></div><div class="receipt-images"><a v-for="image in transaction.receipt.images" :key="image.id" :href="`/receipt-images/${image.id}`" target="_blank" rel="noopener"><img :src="`/receipt-images/${image.id}`" alt="Original receipt — open full size"/></a></div><p class="muted small">Uploaded {{ new Date(transaction.receipt.created_at).toLocaleString('en-US',{timeZone:'America/New_York'}) }} ET. This is separate from the purchase date.</p><div class="extraction-box"><strong>{{ transaction.receipt.status === 'queued' ? 'Extraction queued' : transaction.receipt.status === 'failed' ? 'Extraction needs another try' : 'Extraction complete' }}</strong><p>{{ transaction.receipt.error || (transaction.receipt.status === 'queued' ? 'You can close this page. A running queue worker will process these images.' : 'Corrected fields stay yours when you reprocess.') }}</p><p v-if="transaction.receipt.provider === 'fake'" class="amber-text">Fake result · no image was read.</p><button class="button secondary full" type="button" @click="retry" :disabled="retrying || form.isDirty">{{ retrying ? 'Queueing…' : 'Retry extraction' }}</button><small v-if="form.isDirty">Save your edits before retrying.</small></div><details class="extraction-history"><summary>Extraction history · {{ transaction.receipt.runs?.length ?? 0 }} attempts</summary><div v-for="run in transaction.receipt.runs" :key="run.id"><strong>Attempt {{ run.generation }} · {{ run.provider }} · {{ run.version }}</strong><pre>{{ run.output ? JSON.stringify(run.output,null,2) : run.error }}</pre></div></details></aside>
<section><div v-if="transaction.review_status === 'needs_review' || duplicates.length" class="review-notice"><strong>A few details to check</strong><ul><li v-for="reason in transaction.review_reasons" :key="reason">{{ reason }}</li></ul><p v-if="duplicates.length">Possible duplicate: <Link v-for="d in duplicates" :key="d.id" :href="`/transactions/${d.id}`">{{ d.merchant }} · {{ d.purchase_date }} (#{{d.id}}) </Link>. Compare the originals. Nothing has been merged.</p></div><form @submit.prevent="save" class="edit-panel"><div class="section-heading"><h2>The record</h2><span class="muted small">Edit only what needs it.</span></div><Errors :errors="form.errors"/><div class="form-grid"><label class="span-2">Merchant<input v-model="form.merchant" placeholder="Unknown merchant" maxlength="200"/></label><label>Purchase date<input v-model="form.purchase_date" type="date"/></label><label>Time, if printed<input v-model="form.purchase_time" type="time" step="1"/></label><label>Total<input v-model="form.amount" inputmode="decimal" placeholder="Unknown"/></label><label>Currency<select v-model="form.currency"><option :value="null">Unknown currency</option><option v-for="c in currencies" :key="c">{{ c }}</option></select></label><label>Payment account<select v-model="form.account_id"><option :value="null">Unknown / not assigned</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{ a.nickname }}</option></select></label><label>Category<select v-model="form.category"><option :value="null">Uncategorized</option><option v-for="c in categories" :key="c">{{ c }}</option></select></label></div><p class="muted small">Time is the local time printed on the receipt; timezone is not inferred. <Link href="/accounts">Manage payment accounts ↗</Link></p>
<div class="section-heading item-heading"><h2>Items <span class="count">{{ form.items.length }}</span></h2><button type="button" class="text-button" @click="form.items.push({description:null,quantity:null,amount:null,category:null})">+ Add item</button></div><p v-if="!form.items.length" class="muted">No readable items yet. You can still record the total.</p><div v-for="(item,i) in form.items" :key="i" class="item-editor"><label class="span-2">Description<input v-model="item.description" placeholder="Item description" maxlength="300"/></label><label>Quantity<input v-model="item.quantity" inputmode="decimal" placeholder="Unknown"/></label><label>Line total<input v-model="item.amount" inputmode="decimal" placeholder="Unknown"/></label><label>Category<select v-model="item.category"><option :value="null">Uncategorized</option><option v-for="c in categories" :key="c">{{ c }}</option></select></label><button type="button" class="text-button" @click="form.items.splice(i,1)">Remove item</button></div><p class="muted small">Item amounts are line totals. They are never added to the transaction total in your spending summary.</p><div class="review-controls"><label>Review status<select v-model="form.review_status"><option value="needs_review">Still needs review</option><option value="reviewed">Reviewed — details checked</option></select></label><label class="check"><input v-model="form.excluded" type="checkbox"/>Exclude this record from spending totals</label><small>Use this for a duplicate. The original receipt is kept.</small></div><button class="button primary full" :disabled="form.processing">{{ form.processing ? 'Saving…' : 'Save changes' }} <span>✓</span></button><p class="muted small">Reviewing a receipt never marks it as bank-reconciled.</p></form></section></div></AppShell></template>
